create table if not exists public.research_c0197_pregw3_experiment_runs (
  run_key text primary key,
  experiment_key text not null,
  change_id text not null default 'C0197',
  frozen_at timestamptz not null,
  definition jsonb not null,
  decision text not null,
  research_only boolean not null default true check (research_only),
  model_effect_enabled boolean not null default false check (not model_effect_enabled),
  created_at timestamptz not null default clock_timestamp()
);

create table if not exists public.research_c0197_pregw3_experiment_snapshots (
  id bigint generated by default as identity primary key,
  run_key text not null references public.research_c0197_pregw3_experiment_runs(run_key),
  experiment_key text not null,
  variant_key text not null,
  gameweek integer not null,
  match_id bigint references public.matches(id),
  fixture text not null,
  score numeric,
  rank integer,
  route text,
  confidence numeric,
  coverage numeric,
  features jsonb not null default '{}'::jsonb,
  research_only boolean not null default true check (research_only),
  model_effect_enabled boolean not null default false check (not model_effect_enabled),
  created_at timestamptz not null default clock_timestamp(),
  unique(run_key,variant_key,match_id)
);

alter table public.research_c0197_pregw3_experiment_runs enable row level security;
alter table public.research_c0197_pregw3_experiment_snapshots enable row level security;
revoke all on public.research_c0197_pregw3_experiment_runs from anon,authenticated;
revoke all on public.research_c0197_pregw3_experiment_snapshots from anon,authenticated;
revoke all on sequence public.research_c0197_pregw3_experiment_snapshots_id_seq from anon,authenticated;

create or replace function private.block_c0197_pregw3_experiment_mutation_v01()
returns trigger language plpgsql set search_path=public,private,pg_temp as $$
begin raise exception 'C0197 pre-GW3 experiment evidence is append-only'; end $$;
revoke all on function private.block_c0197_pregw3_experiment_mutation_v01() from public,anon,authenticated;

drop trigger if exists research_c0197_pregw3_runs_append_only on public.research_c0197_pregw3_experiment_runs;
create trigger research_c0197_pregw3_runs_append_only before update or delete on public.research_c0197_pregw3_experiment_runs for each row execute function private.block_c0197_pregw3_experiment_mutation_v01();
drop trigger if exists research_c0197_pregw3_snapshots_append_only on public.research_c0197_pregw3_experiment_snapshots;
create trigger research_c0197_pregw3_snapshots_append_only before update or delete on public.research_c0197_pregw3_experiment_snapshots for each row execute function private.block_c0197_pregw3_experiment_mutation_v01();

