create or replace function private.c0197_pregw3_experiment_status_v01()
returns jsonb language sql stable set search_path=public,private,pg_temp as $$
select jsonb_build_object(
 'change_id','C0197','frozen_at','2026-09-04T07:29:02.603647Z',
 'runs',(select count(*) from public.research_c0197_pregw3_experiment_runs),
 'snapshots',(select count(*) from public.research_c0197_pregw3_experiment_snapshots),
 'experiments',(select coalesce(jsonb_agg(x),'[]'::jsonb) from (select experiment_key,count(*) variants from public.research_c0197_pregw3_experiment_snapshots group by experiment_key order by experiment_key)x),
 'model_effect_enabled',false
); $$;
revoke all on function private.c0197_pregw3_experiment_status_v01() from public,anon,authenticated;